const std=@import("std");
const u=@import("unifier.zig");
const p=@import("parser.zig");
pub const Entry=struct { name:[]const u8,value:*Value };
pub const Environment=[]const Entry;
pub const Value=struct { kind:enum{integer,boolean,string,pair,list,closure,builtin},integer:i64=0,string:[]const u8="",items:[]const *Value=&.{},parameter:[]const u8="",body:?*p.Node=null,environment:Environment=&.{} };
pub fn value(kind:@FieldType(Value,"kind")) *Value { return u.create(Value,.{.kind=kind}); }
pub fn integer(n:i64) *Value { const v=value(.integer); v.integer=n; return v; }
pub fn boolean(n:bool) *Value { const v=value(.boolean); v.integer=@intFromBool(n); return v; }
pub fn string(s:[]const u8) *Value { const v=value(.string); v.string=s; return v; }
pub fn collection(kind:@FieldType(Value,"kind"),items:[]const *Value) *Value { const v=value(kind); const copy=u.alloc(*Value,items.len); @memcpy(copy,items); v.items=copy; return v; }
pub fn extend(env:Environment,entry:Entry) Environment { var out:std.ArrayList(Entry)=.empty; for(env) |old| if(!u.eq(old.name,entry.name)) u.append(Entry,&out,old); u.append(Entry,&out,entry); return out.items; }
pub fn escaped(s:[]const u8) []const u8 { var out:u.Text=.{}; out.put("\"",.{}); for(s) |c| switch(c) {'\\'=>out.put("\\\\",.{}),'"'=>out.put("\\\"",.{}),'\n'=>out.put("\\n",.{}),'\t'=>out.put("\\t",.{}),else=>out.put("{c}",.{c})}; out.put("\"",.{}); return out.data.items; }
pub fn print(v:*const Value) []const u8 { switch(v.kind) { .integer=>return u.fmt("{d}",.{v.integer}),.boolean=>return if(v.integer==0) "false" else "true",.string=>return escaped(v.string),.closure,.builtin=>return "<fun>",.pair=>return u.fmt("({s}, {s})",.{print(v.items[0]),print(v.items[1])}),.list=>{ var out:u.Text=.{}; out.put("[",.{}); for(v.items,0..) |x,i| { if(i>0) out.put("; ",.{}); out.put("{s}",.{print(x)}); } out.put("]",.{}); return out.data.items; } } }
pub const Evaluator=struct {
    failure:?u.Failure=null,calls:usize=0,
    const Error=error{Runtime};
    fn fail(self:*Evaluator,pos:u.Position,comptime s:[]const u8,args:anytype) Error { self.failure=.{.position=pos,.message=u.fmt(s,args)}; return error.Runtime; }
    fn checked(self:*Evaluator,n:i64,pos:u.Position) Error!*Value { if(n < -2147483648 or n > 2147483647) return self.fail(pos,"integer overflow",.{}); return integer(n); }
    pub fn compare(self:*Evaluator,a:*Value,b:*Value,pos:u.Position) Error!std.math.Order {
        switch(a.kind) { .integer,.boolean=>return std.math.order(a.integer,b.integer),.string=>return std.mem.order(u8,a.string,b.string),.closure,.builtin=>return self.fail(pos,"functional value compared",.{}),.pair,.list=>{ for(a.items[0..@min(a.items.len,b.items.len)],b.items[0..@min(a.items.len,b.items.len)]) |x,y| { const result=try self.compare(x,y,pos); if(result!=.eq) return result; } return std.math.order(a.items.len,b.items.len); } }
    }
    pub fn expression(self:*Evaluator,n:*p.Node,env:Environment) Error!*Value {
        const k=n.kind;
        if(u.eq(k,"integer")) return integer(std.fmt.parseInt(i64,n.value,10) catch unreachable); if(u.eq(k,"boolean")) return boolean(u.eq(n.value,"true")); if(u.eq(k,"string")) return string(n.value);
        if(u.eq(k,"name")) { for(env) |entry| if(u.eq(entry.name,n.value)) return entry.value; unreachable; }
        if(u.eq(k,"fun")) { const v=value(.closure); v.parameter=n.value; v.body=n.children[0]; v.environment=env; return v; }
        if(u.eq(k,"apply")) { const f=try self.expression(n.children[0],env); const argument=try self.expression(n.children[1],env); self.calls+=1;
            if(f.kind==.closure) { const local=if(u.eq(f.parameter,"_")) f.environment else extend(f.environment,.{.name=f.parameter,.value=argument}); return self.expression(f.body.?,local); }
            if(u.eq(f.string,"fst")) return argument.items[0]; if(u.eq(f.string,"snd")) return argument.items[1]; if(u.eq(f.string,"not")) return boolean(argument.integer==0); if(u.eq(f.string,"string_of_int")) return string(u.fmt("{d}",.{argument.integer})); return self.fail(n.position,"failure {s}",.{print(argument)});
        }
        if(u.eq(k,"neg")) return self.checked(-(try self.expression(n.children[0],env)).integer,n.operator_position);
        if(u.eq(k,"if")) { const condition=try self.expression(n.children[0],env); return self.expression(n.children[if(condition.integer!=0) @as(usize,1) else 2],env); }
        if(u.eq(k,"binary")) {
            const a=try self.expression(n.children[0],env); const op=n.value;
            if(u.eq(op,"&&") and a.integer==0) return a; if(u.eq(op,"||") and a.integer!=0) return a; const b=try self.expression(n.children[1],env);
            if(u.eq(op,"&&") or u.eq(op,"||")) return b;
            if(u.eq(op,"+")) return self.checked(a.integer+b.integer,n.operator_position); if(u.eq(op,"-")) return self.checked(a.integer-b.integer,n.operator_position); if(u.eq(op,"*")) return self.checked(a.integer*b.integer,n.operator_position);
            if(u.eq(op,"/") or u.eq(op,"mod")) { if(b.integer==0) return self.fail(n.operator_position,"division by zero",.{}); const quotient=@divTrunc(a.integer,b.integer); return self.checked(if(u.eq(op,"/")) quotient else a.integer-b.integer*quotient,n.operator_position); }
            if(u.eq(op,"^")) return string(u.fmt("{s}{s}",.{a.string,b.string}));
            if(u.eq(op,"::")) { const items=u.alloc(*Value,b.items.len+1); items[0]=a; @memcpy(items[1..],b.items); return collection(.list,items); }
            const order=try self.compare(a,b,n.operator_position); return boolean(if(u.eq(op,"=")) order==.eq else if(u.eq(op,"<>")) order!=.eq else if(u.eq(op,"<")) order==.lt else if(u.eq(op,">")) order==.gt else if(u.eq(op,"<=")) order!=.gt else order!=.lt);
        }
        if(u.eq(k,"pair") or u.eq(k,"list")) { const items=u.alloc(*Value,n.children.len); for(n.children,items) |child,*v| v.*=try self.expression(child,env); return collection(if(u.eq(k,"pair")) .pair else .list,items); }
        if(u.eq(k,"match")) { const target=try self.expression(n.children[0],env); for(n.arms) |arm| { var entries:std.ArrayList(Entry)=.empty; if(try self.match(arm.pattern,target,&entries)) { var local=env; for(entries.items) |entry| local=extend(local,entry); return self.expression(arm.expression,local); } } return self.fail(n.position,"match failure",.{}); }
        return self.expression(n.children[0],try self.group(n,env));
    }
    pub fn group(self:*Evaluator,n:*p.Node,env:Environment) Error!Environment {
        var entries:std.ArrayList(Entry)=.empty;
        for(n.bindings) |binding| { const v=try self.expression(binding.expression,env); u.append(Entry,&entries,.{.name=binding.name,.value=v}); }
        var out=env; for(entries.items) |entry| out=extend(out,entry); if(n.recursive) for(entries.items) |entry| { entry.value.environment=out; }; return out;
    }
    fn match(self:*Evaluator,n:*p.Node,v:*Value,entries:*std.ArrayList(Entry)) Error!bool {
        const k=n.kind; if(u.eq(k,"wildcard")) return true; if(u.eq(k,"name")) { u.append(Entry,entries,.{.name=n.value,.value=v}); return true; }
        if(u.eq(k,"integer")) return v.integer==(std.fmt.parseInt(i64,n.value,10) catch unreachable); if(u.eq(k,"string")) return u.eq(v.string,n.value); if(u.eq(k,"boolean")) return (v.integer!=0)==u.eq(n.value,"true");
        if(u.eq(k,"cons")) { if(v.items.len==0) return false; if(!try self.match(n.children[0],v.items[0],entries)) return false; return self.match(n.children[1],collection(.list,v.items[1..]),entries); }
        if(v.items.len!=n.children.len) return false; for(n.children,v.items) |child,item| if(!try self.match(child,item,entries)) return false; return true;
    }
};

const std=@import("std");
const u=@import("unifier.zig");
const p=@import("parser.zig");
pub const Entry=struct { name:[]const u8,scheme:u.Scheme,mark:?*p.Mark=null };
pub const Environment=[]const Entry;
pub fn lookup(env:Environment,name:[]const u8) ?Entry { for(env) |entry| if(u.eq(entry.name,name)) return entry; return null; }
pub fn extend(env:Environment,entry:Entry) Environment { var out:std.ArrayList(Entry)=.empty; for(env) |old| if(!u.eq(old.name,entry.name)) u.append(Entry,&out,old); u.append(Entry,&out,entry); return out.items; }
pub fn distance(a:[]const u8,b:[]const u8) usize { const row=u.alloc(usize,b.len+1); for(row,0..) |*v,i| v.*=i; for(a,1..) |x,i| { var diagonal=row[0]; row[0]=i; for(b,1..) |y,j| { const old=row[j]; row[j]=@min(@min(row[j]+1,row[j-1]+1),diagonal+@intFromBool(x!=y)); diagonal=old; } } return row[b.len]; }
pub const Infer=struct {
    failure:?u.Failure=null,locals:std.ArrayList(*p.Binding)=.empty,marks:std.ArrayList(*p.Mark)=.empty,
    const Error=error{Type};
    pub fn fail(self:*Infer,pos:u.Position,comptime message:[]const u8,args:anytype) Error { self.failure=.{.position=pos,.message=u.fmt(message,args)}; return error.Type; }
    pub fn check(self:*Infer,expected:*u.Type,found:*u.Type,pos:u.Position) Error!void {
        if(u.unify(expected,found)) |failed| { var printer:u.TypePrinter=.{}; const e=printer.print(expected,null); const f=printer.print(found,null); var extra:[]const u8="";
            if(failed.infinite) { const a=u.resolve(failed.expected); const v=if(a.kind==.variable) failed.expected else failed.found; const t=if(a.kind==.variable) failed.found else failed.expected; const variable=printer.print(v,null); const typ=printer.print(t,null); extra=u.fmt(" (infinite type {s} = {s})",.{variable,typ}); }
            else if(u.resolve(expected)!=failed.expected or u.resolve(found)!=failed.found) { const first=printer.print(failed.expected,null); const second=printer.print(failed.found,null); extra=u.fmt(" ({s} vs {s})",.{first,second}); }
            return self.fail(pos,"expected {s} but found {s}{s}",.{e,f,extra});
        }
    }
    fn mark(self:*Infer,name:[]const u8,pos:u.Position,top:bool) *p.Mark { const m=u.create(p.Mark,.{.name=name,.position=pos,.top=top}); u.append(*p.Mark,&self.marks,m); return m; }
    pub fn expression(self:*Infer,n:*p.Node,env:Environment) Error!*u.Type {
        const result=try self.expressionInner(n,env); n.typ=result; return result;
    }
    fn expressionInner(self:*Infer,n:*p.Node,env:Environment) Error!*u.Type {
        const kind=n.kind;
        if(u.eq(kind,"integer")) return u.primitive(.integer); if(u.eq(kind,"string")) return u.primitive(.string); if(u.eq(kind,"boolean")) return u.primitive(.boolean);
        if(u.eq(kind,"name")) { const entry=lookup(env,n.value) orelse { var best:?[]const u8=null; var minimum:usize=3; for(env) |candidate| { const d=distance(n.value,candidate.name); if(d<=2 and d<n.value.len and (d<minimum or (d==minimum and (best==null or std.mem.order(u8,candidate.name,best.?)==.lt)))) { best=candidate.name; minimum=d; } } return self.fail(n.position,"unbound variable '{s}'{s}",.{n.value,if(best) |name| u.fmt(" (did you mean '{s}'?)",.{name}) else ""}); }; n.mark=entry.mark; if(entry.mark) |m| m.uses+=1; return u.instantiate(entry.scheme); }
        if(u.eq(kind,"fun")) { const a=u.fresh(); var local=env; if(!u.eq(n.value,"_")) { const pos=if(n.operator_position.line==0) n.position else n.operator_position; const mark_value=self.mark(n.value,pos,false); n.mark=mark_value; local=extend(env,.{.name=n.value,.scheme=.{.typ=a},.mark=mark_value}); } const result=try self.expression(n.children[0],local); return u.construct(.function,a,result); }
        if(u.eq(kind,"apply")) { var function=u.resolve(try self.expression(n.children[0],env)); if(function.kind==.variable) { const a=u.fresh(); const result=u.fresh(); function.link=u.construct(.function,a,result); function=u.resolve(function); } if(function.kind!=.function) { var printer:u.TypePrinter=.{}; return self.fail(n.children[0].position,"expected a function but found {s}",.{printer.print(function,null)}); } const arg=try self.expression(n.children[1],env); try self.check(function.a.?,arg,n.children[1].position); return function.b.?; }
        if(u.eq(kind,"binary")) {
            const op=n.value; var first:*u.Type=undefined; var second:*u.Type=undefined; var result:*u.Type=undefined;
            if(u.eq(op,"::")) { first=u.fresh(); second=u.construct(.list,first,null); result=second; }
            else if(u.eq(op,"^") or u.eq(op,"&&") or u.eq(op,"||")) { first=u.primitive(if(u.eq(op,"^")) .string else .boolean); second=first; result=first; }
            else if(p.precedence(op)==3) { first=u.fresh(); second=first; result=u.primitive(.boolean); }
            else { first=u.primitive(.integer); second=first; result=first; }
            const left=try self.expression(n.children[0],env); try self.check(first,left,n.children[0].position); const right=try self.expression(n.children[1],env); try self.check(second,right,n.children[1].position); return result;
        }
        if(u.eq(kind,"neg")) { const t=try self.expression(n.children[0],env); const integer=u.primitive(.integer); try self.check(integer,t,n.children[0].position); return integer; }
        if(u.eq(kind,"if")) { const cond=try self.expression(n.children[0],env); try self.check(u.primitive(.boolean),cond,n.children[0].position); const a=try self.expression(n.children[1],env); const b=try self.expression(n.children[2],env); try self.check(a,b,n.children[2].position); return a; }
        if(u.eq(kind,"pair")) { const a=try self.expression(n.children[0],env); const b=try self.expression(n.children[1],env); return u.construct(.pair,a,b); }
        if(u.eq(kind,"list")) { const a=u.fresh(); for(n.children) |child| { const t=try self.expression(child,env); try self.check(a,t,child.position); } return u.construct(.list,a,null); }
        if(u.eq(kind,"match")) { const t=try self.expression(n.children[0],env); const result=u.fresh(); for(n.arms) |arm| { var bindings:std.ArrayList(Entry)=.empty; const pt=try self.pattern(arm.pattern,&bindings); try self.check(t,pt,arm.pattern.position); var local=env; for(bindings.items) |entry| local=extend(local,entry); const rt=try self.expression(arm.expression,local); try self.check(result,rt,arm.expression.position); } return result; }
        const local=try self.group(n,env,false); return self.expression(n.children[0],local);
    }
    fn pattern(self:*Infer,n:*p.Node,bindings:*std.ArrayList(Entry)) Error!*u.Type {
        const k=n.kind; var result:*u.Type=undefined;
        if(u.eq(k,"wildcard")) result=u.fresh()
        else if(u.eq(k,"name")) { if(lookup(bindings.items,n.value)!=null) return self.fail(n.position,"variable '{s}' is bound twice in this pattern",.{n.value}); result=u.fresh(); n.mark=self.mark(n.value,n.position,false); u.append(Entry,bindings,.{.name=n.value,.scheme=.{.typ=result},.mark=n.mark}); }
        else if(u.eq(k,"integer")) result=u.primitive(.integer) else if(u.eq(k,"boolean")) result=u.primitive(.boolean) else if(u.eq(k,"string")) result=u.primitive(.string)
        else if(u.eq(k,"pair")) { const a=try self.pattern(n.children[0],bindings); const b=try self.pattern(n.children[1],bindings); result=u.construct(.pair,a,b); }
        else if(u.eq(k,"cons")) { const a=u.fresh(); const left=try self.pattern(n.children[0],bindings); try self.check(a,left,n.children[0].position); const list=u.construct(.list,a,null); const right=try self.pattern(n.children[1],bindings); try self.check(list,right,n.children[1].position); result=list; }
        else { const a=u.fresh(); for(n.children) |child| { const t=try self.pattern(child,bindings); try self.check(a,t,child.position); } result=u.construct(.list,a,null); }
        n.typ=result; return result;
    }
    pub fn group(self:*Infer,n:*p.Node,env:Environment,top:bool) Error!Environment {
        for(n.bindings,0..) |binding,i| { for(n.bindings[0..i]) |old| if(u.eq(old.name,binding.name)) return self.fail(binding.position,"variable '{s}' is bound twice in this let",.{binding.name}); if(n.recursive and !u.eq(binding.expression.kind,"fun")) return self.fail(binding.position,"'{s}' in let rec must be a function",.{binding.name}); }
        const types=u.alloc(*u.Type,n.bindings.len); var recursive_env=env;
        for(n.bindings,0..) |*binding,i| { binding.mark=self.mark(binding.name,binding.position,top); if(n.recursive) { types[i]=u.fresh(); recursive_env=extend(recursive_env,.{.name=binding.name,.scheme=.{.typ=types[i]},.mark=binding.mark}); } }
        for(n.bindings,0..) |binding,i| { const t=try self.expression(binding.expression,if(n.recursive) recursive_env else env); if(n.recursive) try self.check(types[i],t,binding.position) else types[i]=t; }
        n.rec_used=false; for(n.bindings) |binding| if(binding.mark.?.uses>0) { n.rec_used=true; };
        var out=env; for(n.bindings,0..) |*binding,i| { binding.scheme=u.generalize(types[i],env); out=extend(out,.{.name=binding.name,.scheme=binding.scheme.?,.mark=binding.mark}); if(!top) u.append(*p.Binding,&self.locals,binding); } return out;
    }
};

const std=@import("std");
const u=@import("unifier.zig");
pub const Token=struct { kind:enum { name,keyword,integer,string,typevar,symbol,invalid,eof },value:[]const u8,spelling:[]const u8,position:u.Position };
pub fn scan(source:[]const u8,file:usize) []const Token {
    var out:std.ArrayList(Token)=.empty; var at:usize=0; var line:usize=1; var column:usize=1;
    while(at<source.len) {
        if(source[at]==' ' or source[at]=='\n') { if(source[at]=='\n') { line+=1; column=1; } else column+=1; at+=1; continue; }
        const start=at; const position=u.Position{.file=file,.line=line,.column=column}; var kind:@FieldType(Token,"kind")=.symbol; var value:[]const u8=undefined;
        if(std.mem.startsWith(u8,source[at..],"(*")) {
            const end=std.mem.indexOf(u8,source[at+2..],"*)"); if(end==null) { u.append(Token,&out,.{.kind=.invalid,.value="unterminated comment",.spelling=source[at..],.position=position}); while(at<source.len) : (at+=1) if(source[at]=='\n') { line+=1; column=1; } else { column+=1; }; break; }
            const stop=at+2+end.?+2; while(at<stop) : (at+=1) { if(source[at]=='\n') { line+=1; column=1; } else column+=1; } continue;
        } else if(std.ascii.isDigit(source[at])) { at+=1; while(at<source.len and std.ascii.isDigit(source[at])) : (at+=1) {} value=source[start..at]; kind=.integer; const n=std.fmt.parseInt(i64,value,10) catch std.math.maxInt(i64); if(n>2147483647) { kind=.invalid; value="integer literal too large"; } }
        else if(std.ascii.isAlphabetic(source[at]) or source[at]=='_') { at+=1; while(at<source.len and (std.ascii.isAlphanumeric(source[at]) or source[at]=='_' or source[at]=='\'')) : (at+=1) {} kind=.name; value=source[start..at]; for([_][]const u8{"let","rec","and","in","fun","if","then","else","match","with","true","false","mod","val"}) |word| if(u.eq(value,word)) { kind=.keyword; break; }; }
        else if(source[at]=='\'' and at+1<source.len and source[at+1]>='a' and source[at+1]<='z') { at+=2; while(at<source.len and (std.ascii.isAlphanumeric(source[at]) or source[at]=='_')) : (at+=1) {} kind=.typevar; value=source[start..at]; }
        else if(source[at]=='"') {
            at+=1; var decoded:u.Text=.{}; var invalid=false;
            while(at<source.len and source[at]!='"' and source[at]!='\n') {
                if(source[at]=='\\' and at+1<source.len and source[at+1]!='\n') { at+=1; const c:u8=switch(source[at]) {'n'=>'\n','t'=>'\t','\\'=>'\\','"'=>'"',else=>blk:{ invalid=true; break :blk source[at]; }}; decoded.put("{c}",.{c}); at+=1; }
                else { decoded.put("{c}",.{source[at]}); at+=1; }
            }
            if(at==source.len or source[at]!='"') { kind=.invalid; value="unterminated string"; } else { at+=1; kind=if(invalid) .invalid else .string; value=if(invalid) "invalid escape sequence" else decoded.data.items; }
        } else {
            var matched=false; if(at+1<source.len) for([_][]const u8{";;","->","::","||","&&","<=",">=","<>"}) |s| if(u.eq(source[at..at+2],s)) { at+=2; matched=true; break; };
            if(!matched) { if(std.mem.indexOfScalar(u8,":;=<>+-*/^()[],|",source[at])==null) { kind=.invalid; value=u.fmt("illegal character '{c}'",.{source[at]}); } at+=1; }
            if(kind!=.invalid) value=source[start..at];
        }
        u.append(Token,&out,.{.kind=kind,.value=value,.spelling=source[start..at],.position=position}); column+=at-start;
    }
    u.append(Token,&out,.{.kind=.eof,.value="",.spelling="",.position=.{.file=file,.line=line,.column=column}}); return out.items;
}

const std=@import("std");
const u=@import("unifier.zig");
const lexer=@import("lexer.zig");
const p=@import("parser.zig");
const inference=@import("inference.zig");
const evaluator=@import("evaluator.zig");
const Node=p.Node;
const Signature=struct { name:[]const u8,node:*Node,position:u.Position };
fn signatureType(n:*Node,variables:*std.StringHashMap(*u.Type)) *u.Type {
    const k=n.kind; if(u.eq(k,"int")) return u.primitive(.integer); if(u.eq(k,"bool")) return u.primitive(.boolean); if(u.eq(k,"string")) return u.primitive(.string);
    if(u.eq(k,"typevar")) { if(variables.get(n.value)) |t| return t; const t=u.fresh(); variables.put(n.value,t) catch @panic("allocation failed"); return t; }
    return u.construct(if(u.eq(k,"list")) .list else if(u.eq(k,"pair")) .pair else .function,signatureType(n.children[0],variables),if(n.children.len>1) signatureType(n.children[1],variables) else null);
}
fn sameType(a0:*u.Type,b0:*u.Type) bool { const a=u.resolve(a0); const b=u.resolve(b0); if(a==b) return true; if(a.kind!=b.kind or a.kind==.variable) return false; if(a.a!=null and !sameType(a.a.?,b.a.?)) return false; if(a.b!=null and !sameType(a.b.?,b.b.?)) return false; return true; }
fn matchesSignature(a0:*u.Type,b0:*u.Type,map:*std.AutoHashMap(usize,*u.Type)) bool { const a=u.resolve(a0); const b=u.resolve(b0); if(a.kind==.variable) { if(map.get(a.id)) |old| return sameType(old,b); map.put(a.id,b) catch @panic("allocation failed"); return true; } if(a.kind!=b.kind) return false; if(a.a!=null and !matchesSignature(a.a.?,b.a.?,map)) return false; if(a.b!=null and !matchesSignature(a.b.?,b.b.?,map)) return false; return true; }
fn signatureFormat(n:*Node) []const u8 {
